// ── Deterministic particle data (generated once, stable across renders) ──
const PARTICLES = Array.from({ length: 22 }, (_, i) => ({
  id: i,
  x: (i * 37 + 11) % 100,           // 0–100 % left
  y: (i * 53 + 7)  % 100,           // 0–100 % top
  size: 1.5 + ((i * 13) % 3),       // 1.5–4.5 px
  duration: 4 + ((i * 7) % 8),      // 4–12 s
  delay: (i * 0.45) % 6,            // 0–6 s stagger
  driftY: 30 + ((i * 17) % 50),     // 30–80 px upward drift
}))

const AmbientParticles = memo(function AmbientParticles({ isDevSpecial }: { isDevSpecial: boolean }) {
  return (
    <>
      {PARTICLES.map(p => (
        <div
          key={p.id}
          className={`kadence-particle absolute rounded-full pointer-events-none transition-colors duration-700 ${isDevSpecial ? 'bg-[#d4af37]/60 shadow-[0_0_10px_rgba(212,175,55,0.8)]' : 'bg-white/30'}`}
          style={{
            left:   `${p.x}%`,
            top:    `${p.y}%`,
            width:  `${p.size}px`,
            height: `${p.size}px`,
            ['--dur'   as string]: `${p.duration}s`,
            ['--delay' as string]: `${p.delay}s`,
            ['--drift' as string]: `-${p.driftY}px`,
          }}
        />
      ))}
    </>
  )
})

function MagneticChromeText({ children, className, style }: { children: React.ReactNode; className?: string; style?: React.CSSProperties }) {
  const ref = useRef<HTMLHeadingElement>(null)
  
  const x = useMotionValue(0)
  const y = useMotionValue(0)
  
  const springX = useSpring(x, { stiffness: 150, damping: 15, mass: 0.1 })
  const springY = useSpring(y, { stiffness: 150, damping: 15, mass: 0.1 })
  
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!ref.current) return
      const rect = ref.current.getBoundingClientRect()
      const centerX = rect.left + rect.width / 2
      const centerY = rect.top + rect.height / 2
      const distanceX = e.clientX - centerX
      const distanceY = e.clientY - centerY
      
      const distance = Math.sqrt(distanceX * distanceX + distanceY * distanceY)
      const maxDistance = 350
      
      if (distance < maxDistance) {
        const force = 1 - Math.pow(distance / maxDistance, 2)
        const pull = 0.15 * force
        x.set(distanceX * pull)
        y.set(distanceY * pull)
      } else {
        x.set(0)
        y.set(0)
      }
    }
    
    window.addEventListener('mousemove', handleMouseMove)
    return () => window.removeEventListener('mousemove', handleMouseMove)
  }, [x, y])

  return (
    <motion.h3
      ref={ref}
      style={{
        x: springX,
        y: springY,
        background: 'linear-gradient(180deg, #FFE670 0%, #FFB800 35%, #5c4100 45%, #FFF9B0 50%, #FFC600 70%, #E59600 100%)',
        WebkitBackgroundClip: 'text',
        WebkitTextFillColor: 'transparent',
        ...style
      }}
      className={className}
    >
      {children}
    </motion.h3>
  )
}

