import { useRef, useCallback } from 'react'
import { Vibe } from '@/lib/types'
import { SIGNATURE_SONGS } from '@/lib/signatureSongs'
import { vibeService } from '@/lib/vibeService'
import { useUIStore } from '@/store/uiStore'


// How long the cursor must dwell on a card before prefetching begins.
// 150ms filters out rapid cursor sweeps without noticeable lag for intentional hovers.
const PREFETCH_DEBOUNCE_MS = 150

// Dwell threshold (50ms) to filter out fast cursor sweeps during scrolling
const HOVER_DWELL_MS = 50

export function useChartHover() {
  const hoveredVibe = useUIStore((s) => s.hoveredVibe)
  const setHoveredVibe = useUIStore((s) => s.setHoveredVibe)

  const hoverDwellTimeoutRef  = useRef<NodeJS.Timeout | null>(null)
  const prefetchDebounceRef   = useRef<NodeJS.Timeout | null>(null)
  const exitTimeoutRef        = useRef<NodeJS.Timeout | null>(null)
  const hoveredVibeRef        = useRef<Vibe | null>(null)

  const handleHoverStart = useCallback((vibeId: Vibe) => {
    // Immediately cancel any pending exit timer from moving between cards
    if (exitTimeoutRef.current) {
      clearTimeout(exitTimeoutRef.current)
      exitTimeoutRef.current = null
    }

    hoveredVibeRef.current = vibeId
    setHoveredVibe(vibeId)

    // ── Prefetch (debounced 150ms) ───────────────────────────────────────────
    if (vibeService.isCached(vibeId)) return

    if (prefetchDebounceRef.current) clearTimeout(prefetchDebounceRef.current)
    prefetchDebounceRef.current = setTimeout(() => {
      if (hoveredVibeRef.current === vibeId) {
        vibeService.prefetchVibe(vibeId)
      }
    }, PREFETCH_DEBOUNCE_MS)
  }, [setHoveredVibe])

  const handleHoverEnd = useCallback(() => {
    if (hoverDwellTimeoutRef.current) clearTimeout(hoverDwellTimeoutRef.current)
    if (prefetchDebounceRef.current)  clearTimeout(prefetchDebounceRef.current)
    // 50ms grace period on hover exit: allows cursor to traverse the 12px gap
    // between cards without flashing or triggering double re-renders.
    // If entering another card, handleHoverStart cancels this timer immediately (0ms).
    if (exitTimeoutRef.current) clearTimeout(exitTimeoutRef.current)
    exitTimeoutRef.current = setTimeout(() => {
      hoveredVibeRef.current = null
      setHoveredVibe(null)
    }, 50)
  }, [setHoveredVibe])

  return {
    hoveredVibe,

    handleHoverStart,
    handleHoverEnd,
    signatureSongs: SIGNATURE_SONGS,
  }
}

// Reproducible local production smoke/performance sample. Uses an isolated headless profile.
import { spawn } from 'node:child_process'
import fs from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { setTimeout as delay } from 'node:timers/promises'

const label = process.argv[2] || 'sample'
const base = process.env.AUDIT_URL || 'http://localhost:3100'
const out = path.resolve('docs/audit/results/2026-11-15')
await fs.mkdir(out, { recursive: true })
const profile = await fs.mkdtemp(path.join(os.tmpdir(), 'kadence-audit-'))
const browser = spawn(process.env.AUDIT_BROWSER || 'C:/Program Files/BraveSoftware/Brave-Browser/Application/brave.exe', [
  '--headless=new', '--no-first-run', '--no-default-browser-check',
  '--remote-debugging-port=9345', `--user-data-dir=${profile}`, '--window-size=1440,900',
  '--autoplay-policy=no-user-gesture-required', 'about:blank',
], { windowsHide: true, stdio: 'ignore' })
let ws
try {
  let target
  for (let i = 0; i < 50; i++) {
    try { target = (await (await fetch('http://127.0.0.1:9345/json')).json()).find(t => t.type === 'page'); if (target) break } catch {}
    await delay(200)
  }
  if (!target) throw new Error('Audit browser did not start')
  ws = new WebSocket(target.webSocketDebuggerUrl)
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject })
  let sequence = 0
  const pending = new Map()
  const errors = [], failedRequests = [], requests = []
  ws.onmessage = ({ data }) => {
    const m = JSON.parse(data)
    if (m.id) { const p = pending.get(m.id); if (p) { clearTimeout(p.timer); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result) } }
    if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails)
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') errors.push(m.params.entry)
    if (m.method === 'Network.loadingFailed') failedRequests.push(m.params)
    if (m.method === 'Network.responseReceived') requests.push({ url: m.params.response.url, status: m.params.response.status, type: m.params.type })
  }
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++sequence
    const timer = setTimeout(() => { pending.delete(id); reject(new Error(`Timeout: ${method}`)) }, 30000)
    pending.set(id, { resolve, reject, timer }); ws.send(JSON.stringify({ id, method, params }))
  })
  const evaluate = async expression => {
    const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails))
    return r.result.value
  }
  await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable'); await send('Network.enable')
  await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false })
  await send('Page.addScriptToEvaluateOnNewDocument', { source: `
    window.__audit = { frames: [], longTasks: [], lcp: [], cls: 0, audioCreated: 0, audioPlay: [], uploads: [] };
    for (const type of ['longtask','largest-contentful-paint','layout-shift']) {
      try { new PerformanceObserver(list => { for (const e of list.getEntries()) {
        if (type === 'longtask') __audit.longTasks.push({t:e.startTime,d:e.duration});
        if (type === 'largest-contentful-paint') __audit.lcp.push(e.startTime);
        if (type === 'layout-shift' && !e.hadRecentInput) __audit.cls += e.value;
      }}).observe({type, buffered:true}); } catch {}
    }
    let prev; function frame(t) { if(prev) __audit.frames.push({t,d:t-prev}); prev=t; requestAnimationFrame(frame) } requestAnimationFrame(frame);
    const NativeAudio = window.Audio; window.Audio = function(...args) { __audit.audioCreated++; return new NativeAudio(...args) }; window.Audio.prototype = NativeAudio.prototype;
    const nativePlay = HTMLMediaElement.prototype.play; HTMLMediaElement.prototype.play = function() { if(this.tagName==='AUDIO') __audit.audioPlay.push({t:performance.now(),url:this.src}); return nativePlay.call(this) };
    for (const name of ['texImage2D','texSubImage2D']) { const native=WebGL2RenderingContext.prototype[name]; WebGL2RenderingContext.prototype[name]=function(...args) { const c=args.find(x=>x instanceof HTMLCanvasElement); if(c) __audit.uploads.push({t:performance.now(),width:c.width,height:c.height}); return native.apply(this,args) } }
  ` })
  await send('Page.navigate', { url: base })
  await delay(7000)
